using be;
using LinqToDB.Mapping;

namespace database;

public class RuleSetMapping
{
    public static void Configure(FluentMappingBuilder builder)
    {
        var entity = builder.Entity<RuleSet>().HasTableName("rule_sets").HasPrimaryKey(x => x.id);

        // the id is generated by the db (DEFAULT gen_random_uuid(), see DatabaseInitializer)
        entity.Property(x => x.id).HasColumnName("id").HasDbType("uuid").HasSkipOnInsert().HasSkipOnUpdate();
        entity.Property(x => x.effective_from).HasColumnName("effective_from").IsNullable(false);

        // weeks 1-5
        entity.Property(x => x.weeks1to5_month_rate).HasColumnName("weeks1to5_month_rate").IsNullable(false);
        entity.Property(x => x.weeks1to5_earning_start_month).HasColumnName("weeks1to5_earning_start_month").IsNullable(false);
        entity.Property(x => x.weeks1to5_earning_end_month).HasColumnName("weeks1to5_earning_end_month").IsNullable(false);
        entity.Property(x => x.weeks1to5_usage_start_month).HasColumnName("weeks1to5_usage_start_month").IsNullable(false);
        entity.Property(x => x.weeks1to5_usage_start_year_offset).HasColumnName("weeks1to5_usage_start_year_offset").IsNullable(false);
        entity.Property(x => x.weeks1to5_usage_end_month).HasColumnName("weeks1to5_usage_end_month").IsNullable(false);
        entity.Property(x => x.weeks1to5_usage_end_year_offset).HasColumnName("weeks1to5_usage_end_year_offset").IsNullable(false);

        // week 6
        entity.Property(x => x.week6_enabled).HasColumnName("week6_enabled").IsNullable(false);
        entity.Property(x => x.week6_hours_per_month).HasColumnName("week6_hours_per_month").IsNullable(false);
        entity.Property(x => x.week6_earning_start_month).HasColumnName("week6_earning_start_month").IsNullable(false);
        entity.Property(x => x.week6_earning_end_month).HasColumnName("week6_earning_end_month").IsNullable(false);
        entity.Property(x => x.week6_usage_start_month).HasColumnName("week6_usage_start_month").IsNullable(false);
        entity.Property(x => x.week6_usage_start_year_offset).HasColumnName("week6_usage_start_year_offset").IsNullable(false);
        entity.Property(x => x.week6_usage_end_month).HasColumnName("week6_usage_end_month").IsNullable(false);
        entity.Property(x => x.week6_usage_end_year_offset).HasColumnName("week6_usage_end_year_offset").IsNullable(false);

        // main holiday and notice
        entity.Property(x => x.main_holiday_length_days).HasColumnName("main_holiday_length_days").IsNullable(false);
        entity.Property(x => x.main_holiday_start_month).HasColumnName("main_holiday_start_month").IsNullable(false);
        entity.Property(x => x.main_holiday_end_month).HasColumnName("main_holiday_end_month").IsNullable(false);
        entity.Property(x => x.main_holiday_notice_months).HasColumnName("main_holiday_notice_months").IsNullable(false);
        entity.Property(x => x.other_holiday_notice_months).HasColumnName("other_holiday_notice_months").IsNullable(false);

        // standard working week, null = not a working day
        entity.Property(x => x.monday_start).HasColumnName("monday_start").HasDbType("time").IsNullable();
        entity.Property(x => x.monday_end).HasColumnName("monday_end").HasDbType("time").IsNullable();
        entity.Property(x => x.tuesday_start).HasColumnName("tuesday_start").HasDbType("time").IsNullable();
        entity.Property(x => x.tuesday_end).HasColumnName("tuesday_end").HasDbType("time").IsNullable();
        entity.Property(x => x.wednesday_start).HasColumnName("wednesday_start").HasDbType("time").IsNullable();
        entity.Property(x => x.wednesday_end).HasColumnName("wednesday_end").HasDbType("time").IsNullable();
        entity.Property(x => x.thursday_start).HasColumnName("thursday_start").HasDbType("time").IsNullable();
        entity.Property(x => x.thursday_end).HasColumnName("thursday_end").HasDbType("time").IsNullable();
        entity.Property(x => x.friday_start).HasColumnName("friday_start").HasDbType("time").IsNullable();
        entity.Property(x => x.friday_end).HasColumnName("friday_end").HasDbType("time").IsNullable();

        // transfer
        entity.Property(x => x.transfer_allowed).HasColumnName("transfer_allowed").IsNullable(false);
        entity.Property(x => x.transfer_max_days).HasColumnName("transfer_max_days").IsNullable(false);
        entity.Property(x => x.transfer_weeks1to5_deadline_month).HasColumnName("transfer_weeks1to5_deadline_month").IsNullable(false);
        entity.Property(x => x.transfer_weeks1to5_deadline_day).HasColumnName("transfer_weeks1to5_deadline_day").IsNullable(false);
        entity.Property(x => x.transfer_week6_deadline_month).HasColumnName("transfer_week6_deadline_month").IsNullable(false);
        entity.Property(x => x.transfer_week6_deadline_day).HasColumnName("transfer_week6_deadline_day").IsNullable(false);

        // holiday debt
        entity.Property(x => x.max_holiday_debt_days).HasColumnName("max_holiday_debt_days").IsNullable(false);
        entity.Property(x => x.non_negative_balance_month).HasColumnName("non_negative_balance_month").IsNullable(false);
        entity.Property(x => x.non_negative_balance_day).HasColumnName("non_negative_balance_day").IsNullable(false);
    }
}
